import re
from .epc_section_generic import EpcSectionGeneric, EpcLine
from ..utils.logger import logger


class SectionUpf(EpcSectionGeneric):
    """
    Section "Upf" is a part of epc.lua config file.
    Generated content base on epc.yaml.
    Example generated for CLOUD_MP_CUS_MP:

    exec("set_upf id=1 daemon=:10000 type=simulated addr=1.2.4.1/24 ngu=10.0.1.1 ngu_snd_buff_size=20M ngu_rcv_buff_size=20M
         ngu_read_packets_threshold=20")
    """

    def _prepare_section_content(self, epc_config, *args, **kwargs):
        upf_keys = filter(self._filter_upf, sorted(epc_config.keys()))
        if not upf_keys:
            return

        logger.debug("Generating UPF section")
        subsection = []
        for upf in upf_keys:
            upf_data = epc_config[upf]
            upf_num = re.match(r'upf(?P<upf_num>\d+)', upf).group('upf_num')
            ip_addr = f"{upf_data['ip_addr']}/{upf_data['ip_addr_mask']}"
            ngu_ip_addr = f"{upf_data['ngu_ip_addr']}"

            upf_line = f"set_upf id={upf_num} daemon=:{self.EDAEMON_PORT} type=simulated addr={ip_addr} " \
                       f"ngu={ngu_ip_addr} ngu_snd_buff_size=20M ngu_rcv_buff_size=20M ngu_read_packets_threshold=20"
            subsection.append(EpcLine(line=upf_line, exec=True, tab_count=0))

        self._section_content.append(subsection)

    @staticmethod
    def _filter_upf(s):
        return re.match(r'upf\d+', s) is not None
